test('saved strength estimates can be corrected without changing group feedback or session timestamps',()=>{const a=app();a.run("startFreeWorkout({exercise:'冲浪起乘',type:'bodyweight',sets:'1',reps:'10'});draft.startedAt=Date.now()-600000;completeSet(0);saveSetFeedback('吃力');saveStrengthEstimates({weight:'70','minutes-0':'5'});finishWorkout()");const end=a.run('records[0].endedAt');a.run('recordEditDialog(records[0].id)');assert.match(a.element('workout-content').innerHTML,/strength-minutes-0/);assert.equal(a.run("updateRecord(records[0].id,{name:'冲浪练习',date:localDate(),minutes:'10','reps-0-0':'12','strength-minutes-0':'4','strength-weight-0':'80'})"),true);assert.equal(a.run('records[0].items[0].calorieEstimate.calories'),16);assert.equal(a.run('records[0].items[0].sets[0].feel'),'吃力');assert.equal(a.run('records[0].endedAt'),end);assert.equal(a.run('homeData().calories'),16);const stored=a.storage.get('nextstep.records');assert.equal(a.run("updateRecord(records[0].id,{name:'冲浪练习',date:localDate(),minutes:'1','reps-0-0':'12'})"),false);assert.equal(a.storage.get('nextstep.records'),stored)});
test('each completed set requests feedback, survives reload and keeps its rest deadline',()=>{const a=app();a.run("startFreeWorkout({exercise:'冲浪起乘',type:'bodyweight',sets:'2',reps:'10'});completeSet(0)");assert.match(a.element('workout-content').innerHTML,/这一组感觉怎么样/);const before=JSON.parse(a.storage.get('nextstep.draft'));a.run('completeSet(0);completeSet(1)');assert.equal(a.run('draft.items[0].sets[1].done'),false);assert.equal(a.run('restEnd'),before.restEnd);const b=app({'nextstep.draft':before});b.run('workoutDialog()');assert.match(b.element('workout-content').innerHTML,/这一组感觉怎么样/);assert.equal(b.run("saveSetFeedback('吃力')"),true);assert.equal(b.run('draft.items[0].sets[0].feel'),'吃力');assert.equal(b.run('restEnd'),before.restEnd);assert.match(b.element('workout-content').innerHTML,/休息一下/);b.run('endRest();completeSet(1)');const end=b.run('draft.finishedAt');assert.match(b.element('workout-content').innerHTML,/这一组感觉怎么样/);b.run("saveSetFeedback('合适');finishWorkout()");assert.equal(b.run('records[0].endedAt'),end);assert.equal(b.run('records[0].items[0].sets[1].feel'),'合适');assert.equal(b.run('records[0].volume'),0)});
test('set feedback write failure keeps the question and data retryable',()=>{const a=app();a.run("startFreeWorkout({exercise:'冲浪哑铃划水',sets:'2',reps:'10',weight:'1'});completeSet(0)");const stored=a.storage.get('nextstep.draft');a.context.localStorage.setItem=()=>{throw Error('quota')};assert.equal(a.run("saveSetFeedback('轻松')"),false);assert.equal(a.storage.get('nextstep.draft'),stored);assert.equal(a.run('draft.items[0].sets[0].feel'),'未反馈');assert.ok(a.run('pendingSetFeedback()'));a.context.localStorage.setItem=(k,v)=>a.storage.set(k,v);assert.equal(a.run("saveSetFeedback('轻松')"),true);assert.equal(a.run('pendingSetFeedback()'),null)});
