test('strength calories save explicit active minutes and aggregate without repeating sport or session time',()=>{const a=app();const noon=new Date();noon.setHours(12,0,0,0);a.context.Date=class extends Date{constructor(...args){super(...(args.length?args:[noon.getTime()]))}static now(){return noon.getTime()}};a.run("startSession();draft.startedAt=Date.now()-3600000;startFreeWorkout({exercise:'冲浪哑铃划水',sets:'1',reps:'10',weight:'1'});completeSet(0);saveSetFeedback('合适');startFreeWorkout({exercise:'冲浪起乘',type:'bodyweight',sets:'1',reps:'10'});completeSet(0);saveSetFeedback();saveSport({sport:'walk',minutes:'10',weight:'70',date:localDate(new Date(draft.startedAt))});finishReview()");const end=a.run('draft.finishedAt');assert.equal(a.run("saveStrengthEstimates({weight:'70','minutes-0':'10','minutes-1':'5'})"),true);assert.equal(a.run('draft.finishedAt'),end);assert.equal(a.run('draft.items[0].calorieEstimate.calories'),41);assert.equal(a.run('draft.items[1].calorieEstimate.calories'),18);a.run('finishWorkout()');assert.equal(a.run('records[0].minutes'),60);assert.equal(a.run('records[0].activities.length'),1);assert.equal(a.run('homeData().calories'),103);assert.equal(a.run('homeData().partialCalories'),false);a.run("recordDialog(records[0].id,'basis')");assert.match(a.element('workout-content').innerHTML,/3.5 × 70 × 10 ÷ 60 ≈ 41 kcal/);assert.equal(a.run('exportData().records[0].items[0].calorieEstimate.activityCode'),'02054')});
test('strength estimate rejects invalid inputs and excess active time and keeps failed writes retryable',()=>{const a=app();a.run("startFreeWorkout({exercise:'冲浪起乘',type:'bodyweight',sets:'1',reps:'10'});draft.startedAt=Date.now()-600000;completeSet(0);saveSetFeedback()");for(const values of [{weight:'NaN','minutes-0':'1'},{weight:'70','minutes-0':'Infinity'},{weight:'70','minutes-0':'11'}]){a.context.values=values;assert.equal(a.run('saveStrengthEstimates(values)'),false);assert.equal(a.run('draft.items[0].calorieEstimate'),undefined)}const original=a.storage.get('nextstep.draft');a.context.localStorage.setItem=()=>{throw Error('quota')};assert.equal(a.run("saveStrengthEstimates({weight:'70','minutes-0':'5'})"),false);assert.equal(a.storage.get('nextstep.draft'),original);a.context.localStorage.setItem=(k,v)=>a.storage.set(k,v);a.run("saveStrengthEstimates({weight:'70','minutes-0':'5'})");assert.equal(a.run('draft.items[0].calorieEstimate.calories'),18);a.run("saveStrengthEstimates({weight:'70','minutes-0':''})");assert.equal(a.run('draft.items[0].calorieEstimate'),undefined)});
