function app(initial={},source){const listeners=new Map();const elements=new Map();const element=id=>{if(!elements.has(id))elements.set(id,{textContent:'',innerHTML:'',classList:{add(){},remove(){}},addEventListener(){},showModal(){this.open=true},close(){this.open=false}});return elements.get(id)};const storage=new Map(Object.entries(initial).map(([k,v])=>[k,JSON.stringify(v)]));const context=vm.createContext({Date,console,setInterval(){},setTimeout(){},clearTimeout(){},location:{hash:''},localStorage:{getItem:k=>storage.get(k)||null,setItem:(k,v)=>storage.set(k,v),removeItem:k=>storage.delete(k)},document:{querySelector:()=>({style:{}}),getElementById:element,addEventListener(type,fn){if(!listeners.has(type))listeners.set(type,[]);listeners.get(type).push(fn)}},window:{addEventListener(){}}});for(const name of ['foods.js','nutrition.js'])vm.runInContext(fs.readFileSync(require('node:path').join(__dirname,'../dist',name),'utf8'),context);vm.runInContext(source||fs.readFileSync(require('node:path').join(__dirname,'../dist/app.js'),'utf8'),context);return {run:code=>vm.runInContext(code,context),context,storage,element,listeners}}

test('bulk add and replacement use the same intersected catalog and selection-specific actions',()=>{
 const a=app();a.run("openTrainingShop();Object.assign(trainingCart,{query:'俯卧撑',equipment:'徒手',category:'arms',tab:'all'})");const bulk=a.run('trainingShopResults()'),single=a.run("projectResults('free','俯卧撑','徒手','arms')"),swap=a.run("projectResults('swap','俯卧撑','徒手','arms')");
 const names=(html,attr)=>[...html.matchAll(new RegExp(attr+'="([^"]+)"','g'))].map(m=>m[1]);assert.deepEqual(names(bulk,'data-shop-add'),names(single,'data-project-key'));assert.deepEqual(names(single,'data-project-key'),names(swap,'data-project-key'));assert.ok(names(bulk,'data-shop-add').includes('俯卧撑'));assert.match(bulk,/可连续加入清单/);assert.match(single,/再填写参数/);assert.match(swap,/替换未完成组/);assert.equal(a.run('draft'),null);
});
